#!/usr/bin/env bash
set -euo pipefail
ROUND="${1:?r1 or r2}"; [[ "$ROUND" == r1 || "$ROUND" == r2 ]] || exit 2
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; PROJECT="$(cd "$HERE/../.." && pwd)"; REPO="$(cd "$PROJECT/.." && pwd)"; cd "$REPO"
if command -v module >/dev/null 2>&1; then module purge >/dev/null 2>&1 || true; module load StdEnv/2023 python/3.11 rdkit/2025.09.4; module load cuda/12.6 2>/dev/null || true; fi
PY="${SUCC_PYTHON_BIN:-/home/bdong/.venvs/molscribe_overlay/bin/python}"; SEED=7; P6="$PROJECT/outputs/p6_unified_transition_policy_v1/seed_${SEED}"; P814="$PROJECT/outputs/p8_1_4_full_smiles_multitask_r1/seed_${SEED}"; DIRECT="$PROJECT/outputs/direct_smiles_denovo_2p7p_v2_mixed_condition"; JOINT="$PROJECT/outputs/unified_smiles_generator_joint_v2"; SHARED="$PROJECT/outputs/p8_1_13_verified_counterfactual_dpo/shared/seed_${SEED}"; OUT="$PROJECT/outputs/p8_1_13_verified_counterfactual_dpo/$ROUND/seed_${SEED}"; BASE="$P814/policy/unified_smiles_generator.pt"; mkdir -p "$OUT/policy" "$OUT/eval/denovo/raw" "$OUT/eval/edit/raw"
[[ -e "$SHARED/PRECOMPUTE_COMPLETE" && -s "$SHARED/preference_pairs.csv" && -s "$SHARED/pair_audit.json" ]] || { echo "P8.1.13 PRE missing" >&2; exit 43; }
export PYTHONPATH="$PROJECT:$PROJECT/experiments/unified_smiles_generator:$PROJECT/experiments/p8_1_7_source_clamped_policy${PYTHONPATH:+:$PYTHONPATH}" P817_SOURCE_CLAMP_SCALE=1.0 TOKENIZERS_PARALLELISM=false OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-8}"
WEIGHT=uniform; [[ "$ROUND" == r2 ]] && WEIGHT=teacher_confidence
"$PY" "$HERE/train_dpo.py" --base-checkpoint "$BASE" --pairs-csv "$SHARED/preference_pairs.csv" --features-dir "$PROJECT/outputs/unified_smiles_generator_suite_v1/feature_variants/train_condition_features_hf_vlm" --denovo-rehearsal-csv "$P814/data/mixed_train.csv" --denovo-features-dir "$P814/data/mixed_features" --output-dir "$OUT/policy" --pair-weighting "$WEIGHT" --epochs "${P8113_EPOCHS:-4}" --seed "$SEED" --device auto
STUDENT="$OUT/policy/unified_smiles_generator.pt"; "$PY" "$HERE/audit_student.py" --base "$BASE" --student "$STUDENT" --pair-audit "$SHARED/pair_audit.json" --round "$ROUND" --output "$OUT/pre_eval_audit.json"
sample(){ local mode="$1" csv="$2" features="$3" seed="$4"; "$PY" "$PROJECT/experiments/p8_1_7_source_clamped_policy/source_clamped_entrypoint.py" sample --checkpoint "$STUDENT" --eval-csv "$csv" --eval-condition-features-dir "$features" --condition-layout unified --output-dir "$OUT/eval/$mode/raw" --prediction-csv "$OUT/eval/$mode/selected.csv" --candidate-output-csv "$OUT/eval/$mode/candidates.csv" --method "p8_1_13_${ROUND}" --decoding-mode sample --num-samples 20 --top-k-candidates 20 --max-candidates 20 --disable-finalizer --smiles-grammar-constraint --max-new-tokens 120 --temperature 0.80 --top-k 32 --top-p 0.95 --parallel-samples 10 --max-parallel-sequences 256 --seed "$seed" --device auto; }
sample denovo "$P6/data/denovo_hard_gate.csv" "$DIRECT/eval_condition_features_hf_vlm" 1813
sample edit "$P6/data/edit_table1_gate.csv" "$JOINT/feature_variants/validation_condition_features_hf_vlm" 2813
"$PY" "$PROJECT/experiments/p8_1_7_source_clamped_policy/normalize_denovo_candidates.py" --input "$OUT/eval/denovo/candidates.csv" --output "$OUT/eval/denovo/candidates_normalized.csv"
"$PY" "$PROJECT/experiments/p6_unified_molecular_transition_policy/evaluate_p6_denovo_gate.py" --eval-csv "$P6/data/denovo_hard_gate.csv" --candidates-csv "$OUT/eval/denovo/candidates_normalized.csv" --output-json "$OUT/eval/denovo/metrics.json" --output-md "$OUT/eval/denovo/report.md" --budgets 1,8,20
for k in 1 8 20; do "$PY" "$PROJECT/scripts/evaluate_moledit_table1_anyk.py" --reference "$P6/data/edit_table1_gate.csv" --candidates "$OUT/eval/edit/candidates.csv" --output-dir "$OUT/eval/edit/any${k}" --candidate-limit "$k" --model-name "p8_1_13_${ROUND}_any${k}" --task-filter table1 --missing-oracle-policy fail; done
"$PY" "$PROJECT/scripts/evaluate_moledit_table1_anyk.py" --reference "$P6/data/edit_table1_gate.csv" --candidates "$OUT/eval/edit/candidates.csv" --output-dir "$OUT/eval/edit/candidate20" --candidate-limit 20 --aggregation candidate --model-name "p8_1_13_${ROUND}_candidate20" --task-filter table1 --missing-oracle-policy fail
"$PY" "$PROJECT/experiments/p8_1_7_source_clamped_policy/audit_candidates.py" --checkpoint "$STUDENT" --candidates "$OUT/eval/edit/candidates.csv" --scale 1.0 --output "$OUT/source_audit.json"
"$PY" "$HERE/audit_student.py" --base "$BASE" --student "$STUDENT" --pair-audit "$SHARED/pair_audit.json" --round "$ROUND" --output "$OUT/final_audit.json"; touch "$OUT/COMPLETE"
